package in.delta.checkpoint;
import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class CheckpointServiceTest{@Test void acknowledgingOneInstrumentDoesNotAcknowledgeAnother(){var repo=mock(MarketCheckpointRepository.class);when(repo.findByUserIdAndInstrumentId(anyLong(),anyString())).thenReturn(java.util.Optional.empty());when(repo.save(any())).thenAnswer(x->x.getArgument(0));var s=new CheckpointService(repo);s.acknowledge(1L,"TCS",100,10);verify(repo).save(argThat(c->c.instrumentId.equals("TCS")));verify(repo,never()).findByUserIdAndInstrumentId(1L,"INFY");}}
